<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Offline</title>
<meta name="theme-color" content="#06063A">
<style>body{margin:0;min-height:100vh;display:flex;align-items:center;justify-content:center;background:#06063A;color:#ECF2FF;font:15px/1.5 system-ui,sans-serif;text-align:center;padding:24px}
img{width:72px;height:72px;border-radius:16px;background:#fff;padding:8px}h1{font-size:20px;margin:16px 0 6px}p{color:#9DAAD0;margin:0 0 20px}
button{background:#0090CF;color:#fff;border:0;border-radius:10px;padding:12px 22px;font:600 15px system-ui}</style></head>
<body><div><img src="/icons/icon-192.png" alt=""><h1>No internet connection</h1><p>This app needs the internet to show live stock and billing.<br>Please check your connection and try again.</p>
<button onclick="location.reload()">Try again</button></div></body></html>
